tower, rdoor, ldoor, boom1, boom2, boom3, boom4, boom5 = piece('tower', 'rdoor', 'ldoor', 'boom1', 'boom2', 'boom3', 'boom4', 'boom5')
boom6, magnet, arm, wake1, wake2, wake3, wake4, wake5 = piece('boom6', 'magnet', 'arm', 'wake1', 'wake2', 'wake3', 'wake4', 'wake5')
wake6, wake7, wake8, base, link = piece('wake6', 'wake7', 'wake8', 'base', 'link')

include "smokeunit.lua"

local AttachUnit = Spring.UnitScript.AttachUnit
local DropUnit = Spring.UnitScript.DropUnit
local rad = math.rad
local floor = math.floor
local COB2RAD = math.pi / 32768
local SIG_MOVE = 1
local SIG_STARTDOOROPEN = 2
local s0 = 0
local s1 = 0
local s2 = 0
local s3 = 0
local s4 = 0

local function Blow(list, flags)
	for _, p in ipairs(list) do Explode(p, flags) end
end

local function BoomCalc(a0, a1)
	local l2 = 0
	local l3 = 0
	local l4 = 0
	l2 = GetUnitValue(COB.PIECE_XZ, tower - 1) - a0
	l3 = a1 - GetUnitValue(COB.PIECE_Y, tower - 1) - 3276800
	l4 = GetUnitValue(COB.XZ_HYPOT, l2)
	s1 = GetUnitValue(COB.HYPOT, l4, l3) - 3276800
	s2 = GetUnitValue(COB.XZ_ATAN, l2)
	s3 = GetUnitValue(COB.ATAN, l3, l4)
	s4 = s1 < 14745600 and 1 or 0
end

local function StartDoorOpen()
	Signal(SIG_STARTDOOROPEN)
	SetSignalMask(SIG_STARTDOOROPEN)
	Turn(rdoor, z_axis, rad(89.98), rad(99.98))
	Turn(ldoor, z_axis, rad(-89.98), rad(99.98))
	WaitForTurn(rdoor, z_axis)
	WaitForTurn(ldoor, z_axis)
	Move(rdoor, y_axis, -22.5, 62.5)
	Move(ldoor, y_axis, -22.5, 62.5)
	WaitForMove(ldoor, y_axis)
	WaitForMove(ldoor, y_axis)
	Sleep(5000)
	Move(rdoor, y_axis, 0, 62.5)
	Move(ldoor, y_axis, 0, 62.5)
	WaitForMove(rdoor, y_axis)
	WaitForMove(ldoor, y_axis)
	Turn(rdoor, z_axis, 0, rad(99.98))
	Turn(ldoor, z_axis, 0, rad(99.98))
	WaitForTurn(rdoor, z_axis)
	WaitForTurn(ldoor, z_axis)
end

local function BoomExtend()
	StartThread(StartDoorOpen)
	Turn(tower, y_axis, s2 * COB2RAD, rad(199.95))
	WaitForTurn(tower, y_axis)
	Move(boom1, z_axis, floor(s1 / 6) / 65536, 150)
	Move(boom2, z_axis, floor(s1 / 6) / 65536, 150)
	Move(boom3, z_axis, floor(s1 / 6) / 65536, 150)
	Move(boom4, z_axis, floor(s1 / 6) / 65536, 150)
	Move(boom5, z_axis, floor(s1 / 6) / 65536, 150)
	Move(boom6, z_axis, floor(s1 / 6) / 65536, 150)
	WaitForMove(boom1, z_axis)
	WaitForMove(boom2, z_axis)
	WaitForMove(boom3, z_axis)
	WaitForMove(boom4, z_axis)
	WaitForMove(boom5, z_axis)
	WaitForMove(boom6, z_axis)
	Turn(magnet, x_axis, s3 * COB2RAD, rad(79.98))
	Turn(arm, x_axis, -(s3 * COB2RAD), rad(79.98))
	WaitForTurn(arm, x_axis)
	WaitForTurn(magnet, x_axis)
end

local function BoomToPad()
	StartThread(StartDoorOpen)
	Turn(magnet, x_axis, 0, rad(59.99))
	Turn(arm, x_axis, 0, rad(59.99))
	WaitForTurn(magnet, x_axis)
	WaitForTurn(arm, x_axis)
	Turn(tower, y_axis, 0, rad(199.95))
	Move(boom1, z_axis, 0, 150)
	Move(boom2, z_axis, 0, 150)
	Move(boom3, z_axis, 0, 150)
	Move(boom4, z_axis, 0, 150)
	Move(boom5, z_axis, 0, 150)
	Move(boom6, z_axis, 0, 150)
	WaitForTurn(tower, y_axis)
	WaitForTurn(arm, x_axis)
	WaitForMove(boom1, z_axis)
	WaitForMove(boom2, z_axis)
	WaitForMove(boom3, z_axis)
	WaitForMove(boom4, z_axis)
	WaitForMove(boom5, z_axis)
	WaitForMove(boom6, z_axis)
	Turn(magnet, x_axis, rad(-29.99), rad(59.99))
	Turn(arm, x_axis, rad(29.99), rad(59.99))
	WaitForTurn(arm, x_axis)
end

local function BoomReset()
	Turn(arm, x_axis, 0, rad(59.99))
	Turn(magnet, x_axis, 0, rad(59.99))
	WaitForTurn(arm, x_axis)
	WaitForTurn(magnet, x_axis)
	Turn(tower, y_axis, 0, rad(199.95))
	Move(boom1, z_axis, 0, 125)
	Move(boom2, z_axis, 0, 125)
	Move(boom3, z_axis, 0, 125)
	Move(boom4, z_axis, 0, 125)
	Move(boom5, z_axis, 0, 125)
	Move(boom6, z_axis, 0, 125)
end

function script.Create()
	StartThread(SmokeUnit, {base})
end

local function StartMoving()
	Signal(SIG_MOVE)
	SetSignalMask(SIG_MOVE)
	while true do
		if s0 == 2 or s0 == 1 then
			EmitSfx(wake1, 3)
			EmitSfx(wake2, 3)
			EmitSfx(wake3, 3)
			EmitSfx(wake4, 3)
			EmitSfx(wake5, 3)
			EmitSfx(wake6, 3)
			EmitSfx(wake7, 3)
			EmitSfx(wake8, 3)
			EmitSfx(wake1, 5)
			EmitSfx(wake2, 5)
			EmitSfx(wake3, 5)
			EmitSfx(wake4, 5)
			EmitSfx(wake5, 5)
			EmitSfx(wake6, 5)
			EmitSfx(wake7, 5)
			EmitSfx(wake8, 5)
		end
		Sleep(300)
	end
end

function script.StartMoving()
