function script.SweetSpot()
	return base
end

function script.setSFXoccupy(terrain)
	s0 = terrain
end

-- how far the boom's tip misses a point along the boom (kit model lengths, the arm travel limit): the empty link makes up the rest
local function ReachOffset(xz)
	local root = GetUnitValue(COB.PIECE_XZ, tower - 1)
	Move(link, z_axis, 0)
	return (GetUnitValue(COB.XZ_HYPOT, root - xz) - GetUnitValue(COB.XZ_HYPOT, root - GetUnitValue(COB.PIECE_XZ, link - 1))) / 65536
end

-- the cargo stays where it stands when it is grabbed, instead of jumping to the boom's tip and into the ground
local function ReachCargo(unitid)
	Move(link, z_axis, ReachOffset(GetUnitValue(COB.UNIT_XZ, unitid)))
	Move(link, y_axis, 0)
	Move(link, y_axis, (GetUnitValue(COB.UNIT_Y, unitid) - GetUnitValue(COB.PIECE_Y, link - 1)) / 65536)
end

function script.TransportPickup(unitid)
	BoomCalc(GetUnitValue(COB.UNIT_XZ, unitid), GetUnitValue(COB.UNIT_Y, unitid) + GetUnitValue(COB.UNIT_HEIGHT, unitid))
	if s4 ~= 0 and GetUnitValue(COB.UNIT_ALLIED, unitid) == GetUnitValue(COB.UNIT_ALLIED, GetUnitValue(COB.MY_ID)) then
		SetUnitValue(COB.BUSY, 1)
		BoomExtend()
		ReachCargo(unitid)
		AttachUnit(link, unitid)
		Move(link, z_axis, 0, 150)
		BoomToPad()
		AttachUnit(0, unitid)
		BoomReset()
		SetUnitValue(COB.BUSY, 0)
	end
end

function script.TransportDrop(unitid, x, y, z)
	local pos = floor(x) * 65536 + floor(z) % 65536   -- COB gets the drop point as PACKXZ
	BoomCalc(pos, GetUnitValue(COB.GROUND_HEIGHT, pos) + GetUnitValue(COB.UNIT_HEIGHT, unitid))
	if s4 ~= 0 then
		SetUnitValue(COB.BUSY, 1)
		BoomToPad()
		Move(link, y_axis, (0 - GetUnitValue(COB.UNIT_HEIGHT, unitid)) / 65536)
		AttachUnit(link, unitid)
		BoomExtend()
		-- the cargo comes down on the chosen spot, not short of it and under the ground
		Move(link, z_axis, ReachOffset(pos), 150)
		Move(link, y_axis, (GetUnitValue(COB.GROUND_HEIGHT, pos) - GetUnitValue(COB.PIECE_Y, link - 1) - GetUnitValue(COB.UNIT_HEIGHT, unitid)) / 65536, 150)
		WaitForMove(link, z_axis)
		WaitForMove(link, y_axis)
		DropUnit(unitid)
		Move(link, z_axis, 0)
		BoomReset()
		SetUnitValue(COB.BUSY, 0)
	end
end

function script.Killed(recentDamage, maxHealth)
	local severity = recentDamage / maxHealth * 100
	if severity <= 25 then
		Explode(boom1, SFX.NONE + SFX.NO_HEATCLOUD)
		Blow({boom2, boom3, base, rdoor, ldoor}, SFX.NONE)
		Explode(link, SFX.NONE + SFX.NO_HEATCLOUD)
		Explode(arm, SFX.NONE)
		return 1
	end
	if severity <= 50 then
		Explode(boom1, SFX.NONE + SFX.NO_HEATCLOUD)
		Blow({boom2, boom3}, SFX.SHATTER)
		Blow({base, rdoor, ldoor}, SFX.NONE)
		Explode(link, SFX.FALL + SFX.NO_HEATCLOUD)
		Explode(arm, SFX.NONE)
		return 2
	end
	if severity <= 99 then
		Explode(boom1, SFX.NONE + SFX.NO_HEATCLOUD)
		Blow({boom2, boom3}, SFX.SHATTER)
		Blow({base, rdoor, ldoor}, SFX.NONE)
		Explode(link, SFX.EXPLODE_ON_HIT + SFX.FALL + SFX.SMOKE + SFX.FIRE + SFX.NO_HEATCLOUD)
		Explode(arm, SFX.NONE)
		return 2
	end
	Explode(boom1, SFX.NONE + SFX.NO_HEATCLOUD)
	Explode(boom2, SFX.SHATTER + SFX.EXPLODE_ON_HIT)
	Explode(boom3, SFX.SHATTER)
	Blow({base, rdoor, ldoor}, SFX.NONE)
	Explode(link, SFX.EXPLODE_ON_HIT + SFX.FALL + SFX.SMOKE + SFX.FIRE + SFX.NO_HEATCLOUD)
	Explode(arm, SFX.NONE)
	return 2
end
